<?php $u=require_user('employer');$id=(int)($_GET['id']??0);$term=substr(trim($_GET['search']??''),0,100);$field=$_GET['field']??'';
$sql="SELECT u.id,u.name,p.* FROM juser u JOIN jprofile p ON p.user_id=u.id WHERE u.role='seeker' AND (p.discoverable=1 OR EXISTS(SELECT 1 FROM applications a JOIN eprofile j ON j.id=a.job_id WHERE a.user_id=u.id AND j.employer_id=?))";$params=[$u['id']];if($id){$sql.=' AND u.id=?';$params[]=$id;}else{if($term!==''){$sql.=' AND (u.name LIKE ? OR p.title LIKE ? OR p.skills LIKE ? OR p.location LIKE ?)';array_push($params,...array_fill(0,4,'%'.$term.'%'));}if(in_array($field,$categories,true)){$sql.=' AND p.field=?';$params[]=$field;}}$people=query($sql.' ORDER BY u.name',$params)->fetchAll();if($id&&!$people)http_response_code(404);
$ownedJobs=query('SELECT id,title,required_skills FROM eprofile WHERE employer_id=? ORDER BY id DESC',[$u['id']])->fetchAll();
$selectedId=(int)($_GET['job_id']??0);$selected=null;foreach($ownedJobs as $role)if((int)$role['id']===$selectedId)$selected=$role;
if($selectedId&&!$selected){http_response_code(404);echo '<section class="page"><h1>Role unavailable.</h1></section>';return;}
if($selected){foreach($people as &$person)$person['match']=skill_match($selected['required_skills'],$person['skills']);unset($person);if(!$id)$people=array_values(array_filter($people,fn($p)=>count($p['match']['matched'])>0));usort($people,fn($a,$b)=>($b['match']['score']<=>$a['match']['score'])?:strcasecmp($a['name'],$b['name']));}
?>
<section class="page"><a href="dashboard.php">← My workspace</a><div class="page-heading"><div><h1><?=$id?'Meet your next hire.':'Find the right person.'?></h1><p>Explore skills, experience and specialist interests.</p></div></div><?php if(!$id):?><form class="filters"><div><label for="match-job">Match to your role</label><select id="match-job" name="job_id"><option value="">All candidates</option><?php foreach($ownedJobs as $role):?><option value="<?=h($role['id'])?>" <?=($selectedId==(int)$role['id'])?'selected':''?>><?=h($role['title'])?></option><?php endforeach;?></select></div><div><label for="search">Name, skill or location</label><input id="search" name="search" value="<?=h($term)?>"></div><div><label for="field">Field</label><select id="field" name="field"><option value="">All fields</option><?php foreach($categories as $c):?><option <?=$field===$c?'selected':''?>><?=h($c)?></option><?php endforeach;?></select></div><button class="button">Find candidates ↗</button></form><?php endif;?>
<?php if($selected):?><p class="notice">Matching <?=h($selected['title'])?>: <?=h($selected['required_skills'])?>. Ranked by the share of listed skills matched; this does not assess experience or proficiency.</p><?php endif;?><?php if(!$people):?><p class="empty">No available profiles match this search.</p><?php endif;foreach($people as $person):?><article class="application"><img src="<?=h(avatar($person['field']))?>" width="90" height="90" alt="<?=h($person['field'])?> avatar"><h2><a href="candidates.php?id=<?=h($person['id'])?>&amp;job_id=<?=h($selectedId)?>"><?=h($person['name'])?> ↗</a></h2><p><?=h($person['title'])?> · <?=h($person['location'])?></p><p>Candidate ID: HST-<?=h($person['id'])?> · <?=h($person['field'])?></p><p><strong>Skills:</strong> <?=h($person['skills'])?></p><?php if($selected):?><div class="skill-match"><h3><?=h($person['match']['score'])?>% skill match · <?=count($person['match']['matched'])?>/<?=h($person['match']['total'])?></h3><p><strong>Matched:</strong> <?=h(implode(', ',$person['match']['matched'])?:'None listed')?></p><p><strong>Not listed on profile:</strong> <?=h(implode(', ',$person['match']['missing'])?:'All required skills are listed')?></p></div><?php endif;?><p class="description"><?=nl2br(h($person['bio']))?></p><p><strong>Experience:</strong> <?= $person['experience_years']!==null?h($person['experience_years']).' years':'Not provided' ?><?php if($person['age']!==null):?> · <strong>Age:</strong> <?=h($person['age'])?><?php endif;?></p><p><strong>Education:</strong> <?=h($person['education']?:'Not provided')?></p><?php if($id):?><div class="description"><?=nl2br(h($person['work_history']??''))?></div><?php endif;?><?php if($person['website'] && in_array(strtolower(parse_url($person['website'],PHP_URL_SCHEME)??''),['http','https'],true)):?><a class="text-link" href="<?=h($person['website'])?>" target="_blank" rel="noopener noreferrer">View portfolio ↗</a><?php endif;?>
<?php if($id):$eprofile=query('SELECT id,title FROM eprofile WHERE employer_id=? ORDER BY id DESC',[$u['id']])->fetchAll();$offers=query('SELECT i.*,j.title FROM hiring_invitations i JOIN eprofile j ON j.id=i.job_id WHERE i.employer_id=? AND i.seeker_id=?',[$u['id'],$id])->fetchAll();foreach($offers as $offer):?><p class="notice"><?=h($offer['title'])?> — <?=h($offer['status'])?></p><?php if($offer['status']==='Accepted'):$contact=query('SELECT email FROM juser WHERE id=?',[$id])->fetchColumn();?><a href="mailto:<?=h($contact)?>"><?=h($contact)?></a><?php endif;endforeach;if($eprofile):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="invite"><input type="hidden" name="seeker_id" value="<?=h($id)?>"><label for="job">Send a hiring offer for</label><select id="job" name="job_id"><?php foreach($eprofile as $job):?><option value="<?=h($job['id'])?>"><?=h($job['title'])?></option><?php endforeach;?></select><button class="button">Send offer ↗</button></form><p>The candidate chooses whether to accept. Existing offers for a role are kept.</p><?php else:?><a class="button" href="eprofile.php">Post a role first ↗</a><?php endif;endif;?></article><?php endforeach;?></section>
